import threading
from random import randrange
from time import sleep

terminate = threading.Event()

class Buckets:
    def __init__(self, nbuckets):
        self.nbuckets = nbuckets
        self.values = [randrange(10) for _ in range(nbuckets)]
        self.lock = threading.Lock()

    def __getitem__(self, i):
        return self.values[i]

    def transfer(self, src, dst, amount):
        with self.lock:
            amount = min(amount, self.values[src])
            self.values[src] -= amount
            self.values[dst] += amount

    def snapshot(self):
        # copy of the current state (synchronized)
        with self.lock:
            return self.values[:]

def randomize(buckets: Buckets):
    nbuckets = buckets.nbuckets
    while not terminate.is_set():
        src = randrange(nbuckets)
        dst = randrange(nbuckets)
        if dst != src:
            amount = randrange(20)
            buckets.transfer(src, dst, amount)

def equalize(buckets: Buckets):
    nbuckets = buckets.nbuckets
    while not terminate.is_set():
        src = randrange(nbuckets)
        dst = randrange(nbuckets)
        if dst != src:
            amount = (buckets[src] - buckets[dst]) // 2
            if amount >= 0: buckets.transfer(src, dst, amount)
            else: buckets.transfer(dst, src, -amount)

def print_state(buckets: Buckets):
    snapshot = buckets.snapshot()
    for value in snapshot:
        print("%2d" % value, end = " ")
    print("=", sum(snapshot))

