    def check_perm(self, out = [0] * 10):
        for i in range(10):
            out[i] = 0

        s = str(self.dsum[0])
        for d in s:
            c = ord(d) - self.ord0
            out[c] += 1
            if out[c] > self.count[c]:
                return

        if len(s) == self.len:
            print(self.dsum[0], end = " ")

    def narc2(self, pos, d):
        if not pos:
            self.check_perm()
            return

        while True:
            self.dsum[pos - 1] = self.dsum[pos] + self.power[d]
            self.count[d] += 1
            self.narc2(pos - 1, d)
            self.count[d] -= 1
            if d == 0:
                break
            d -= 1

    def show(self, n):
        self.len = n
        for i in range(len(self.power)):
            self.power[i] = i ** n
        self.dsum[n] = 0
        print(f"length {n}:", end = " ")
        self.narc2(n, 9)
        print()

def main():
